content.text:
{
  "name": "VISA通信传输层",
  "name_en": "VISA Transfer Layer",
  "manufacturer": "",
  "description": "基于 pyVISA 的通用 VISA 通信软件组件，用于通过 GPIB、RS232、USB 或以太网与实验仪器建立会话并收发数据。本身不是具体的物理实验设备，而是面向多种仪器的通信接口层。",
  "description_en": "A generic VISA communication software component based on pyVISA, used to open sessions and exchange data with laboratory instruments over GPIB, RS232, USB, or Ethernet. It is not a specific physical lab device, but a communication layer for many kinds of instruments.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化 VISA 通信会话并打开资源连接。",
      "description_en": "Initialize the VISA communication session and open the resource connection."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 VISA 通信会话。",
      "description_en": "Close the VISA communication session."
    },
    {
      "action_name": "auto-write",
      "description": "向 VISA 资源写入命令或数据。",
      "description_en": "Write a command or data to the VISA resource."
    },
    {
      "action_name": "auto-read",
      "description": "从 VISA 资源读取返回数据。",
      "description_en": "Read returned data from the VISA resource."
    },
    {
      "action_name": "auto-query",
      "description": "发送查询命令并读取响应。",
      "description_en": "Send a query command and read the response."
    }
  ],
  "tag_hints": [
    "VISA communication",
    "pyVISA",
    "instrument communication layer",
    "GPIB",
    "RS232",
    "USB instrument control",
    "Ethernet instrument control"
  ]
}

